import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_02_latency_chain.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_03_context_compaction.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_04_migration_map.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_05_windows_wsl.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_06_capstone_delivery.png",f=JSON.parse('{"title":"模型不背锅：Codex 选型、提速、迁移与完整项目交付方法","description":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。","frontmatter":{"title":"模型不背锅：Codex 选型、提速、迁移与完整项目交付方法","description":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 智能代理七章","readingTime":8,"source":"2026-08-10/ai_codex_06_model_speed_delivery.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-06-model-speed-delivery"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模型不背锅：Codex 选型、提速、迁移与完整项目交付方法"}],["meta",{"property":"og:description","content":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-06-model-speed-delivery"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"模型不背锅：Codex 选型、提速、迁移与完整项目交付方法"}],["meta",{"name":"twitter:description","content":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png"}]],"prev":{"text":"从单兵助手到自动化流水线：Worktree、GitHub、codex exec 与 CI 实战","link":"/ai/ai-codex-05-engineering-automation"},"next":{"text":"把 AI 编程变成组织能力：速查、排障、最佳实践与企业治理","link":"/ai/ai-codex-07-practice-governance"}},"headers":[],"relativePath":"ai/ai-codex-06-model-speed-delivery.md","filePath":"ai/ai-codex-06-model-speed-delivery.md","lastUpdated":null}'),c={name:"ai/ai-codex-06-model-speed-delivery.md"};function p(_,a,m,x,u,b){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="模型不背锅-codex-选型、提速、迁移与完整项目交付方法" tabindex="-1">模型不背锅：Codex 选型、提速、迁移与完整项目交付方法 <a class="header-anchor" href="#模型不背锅-codex-选型、提速、迁移与完整项目交付方法" aria-label="Permalink to &quot;模型不背锅：Codex 选型、提速、迁移与完整项目交付方法&quot;">​</a></h1><p>AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。</p><p>本文归纳 Codex 系列第 30～34 篇，讨论模型选择、速度与上下文、从其他编码代理迁移、Windows 环境，以及如何把这些知识汇总到一个完整项目。文中不绑定易变的具体型号、价格和配额，而是提供能够跨版本使用的决策方法。</p><h2 id="一、选模型之前先给任务分类" tabindex="-1">一、选模型之前先给任务分类 <a class="header-anchor" href="#一、选模型之前先给任务分类" aria-label="Permalink to &quot;一、选模型之前先给任务分类&quot;">​</a></h2><h3 id="_1-1-复杂度决定需要多少推理" tabindex="-1">1.1 复杂度决定需要多少推理 <a class="header-anchor" href="#_1-1-复杂度决定需要多少推理" aria-label="Permalink to &quot;1.1 复杂度决定需要多少推理&quot;">​</a></h3><p>查找符号、修改文案和机械迁移通常不需要最高推理预算；跨模块设计、并发缺陷和陌生代码库诊断，则需要更强的规划与长链推理。让所有任务都使用同一档模型，会在成本、速度或质量上浪费一端。</p><h3 id="_1-2-风险决定需要多少审查" tabindex="-1">1.2 风险决定需要多少审查 <a class="header-anchor" href="#_1-2-风险决定需要多少审查" aria-label="Permalink to &quot;1.2 风险决定需要多少审查&quot;">​</a></h3><p>即使任务本身简单，只要涉及身份、支付、数据迁移或公开接口，仍应提高审查和验证强度。模型能力不能替代风险控制。</p><h3 id="_1-3-工具与环境可能比模型更关键" tabindex="-1">1.3 工具与环境可能比模型更关键 <a class="header-anchor" href="#_1-3-工具与环境可能比模型更关键" aria-label="Permalink to &quot;1.3 工具与环境可能比模型更关键&quot;">​</a></h3><p>模型若无法读取真实日志、运行测试或访问必要文档，再强也只能根据残缺信息猜测。相反，能力适中的模型在清晰范围、完整工具和快速反馈下，往往更稳定。</p><h3 id="_1-4-用小型基准验证选择" tabindex="-1">1.4 用小型基准验证选择 <a class="header-anchor" href="#_1-4-用小型基准验证选择" aria-label="Permalink to &quot;1.4 用小型基准验证选择&quot;">​</a></h3><p>可以从团队真实任务中挑选若干代表样本，比较完成率、修改范围、验证通过率、人工修正次数和总耗时。选择应建立在工作负载证据上，而不是只看榜单或单次惊艳演示。</p><p><img src="'+i+'" alt="图 1：任务复杂度、风险与模型能力的选择矩阵"></p><h2 id="二、速度问题先看端到端链路" tabindex="-1">二、速度问题先看端到端链路 <a class="header-anchor" href="#二、速度问题先看端到端链路" aria-label="Permalink to &quot;二、速度问题先看端到端链路&quot;">​</a></h2><h3 id="_2-1-总耗时不只来自生成文本" tabindex="-1">2.1 总耗时不只来自生成文本 <a class="header-anchor" href="#_2-1-总耗时不只来自生成文本" aria-label="Permalink to &quot;2.1 总耗时不只来自生成文本&quot;">​</a></h3><p>读取仓库、搜索文件、安装依赖、编译、运行测试、等待网络和人工审查都计入交付时间。只盯着模型每秒输出多少字，可能优化了最不重要的一段。</p><h3 id="_2-2-缩小范围是最便宜的加速" tabindex="-1">2.2 缩小范围是最便宜的加速 <a class="header-anchor" href="#_2-2-缩小范围是最便宜的加速" aria-label="Permalink to &quot;2.2 缩小范围是最便宜的加速&quot;">​</a></h3><p>明确相关目录、入口、错误日志和验证命令，可以减少代理无目的搜索。任务边界越清楚，工具调用和无关上下文越少。</p><h3 id="_2-3-给代理快速反馈回路" tabindex="-1">2.3 给代理快速反馈回路 <a class="header-anchor" href="#_2-3-给代理快速反馈回路" aria-label="Permalink to &quot;2.3 给代理快速反馈回路&quot;">​</a></h3><p>优先运行最相关的单元测试或静态检查，确认局部修改后再扩大验证范围。每次都从完整构建开始，会让代理在简单错误上等待太久；只跑局部测试而永不全量验证，又会漏掉集成风险。</p><h3 id="_2-4-缓存与可重建环境同样重要" tabindex="-1">2.4 缓存与可重建环境同样重要 <a class="header-anchor" href="#_2-4-缓存与可重建环境同样重要" aria-label="Permalink to &quot;2.4 缓存与可重建环境同样重要&quot;">​</a></h3><p>复用依赖缓存、构建产物和稳定开发环境可以减少机械等待，但缓存必须有明确失效条件。无法解释来源的旧产物，会制造“本地通过、干净环境失败”的假象。</p><p><img src="'+l+'" alt="图 2：AI 编程端到端耗时的组成与优化点"></p><h2 id="三、上下文管理决定长任务是否失真" tabindex="-1">三、上下文管理决定长任务是否失真 <a class="header-anchor" href="#三、上下文管理决定长任务是否失真" aria-label="Permalink to &quot;三、上下文管理决定长任务是否失真&quot;">​</a></h2><h3 id="_3-1-上下文不是越大越好" tabindex="-1">3.1 上下文不是越大越好 <a class="header-anchor" href="#_3-1-上下文不是越大越好" aria-label="Permalink to &quot;3.1 上下文不是越大越好&quot;">​</a></h3><p>会话历史、日志、文件内容和工具结果都占据注意力。无关内容越多，真正关键的约束越容易被淹没。长上下文提供容量，不代表所有内容都应该装进去。</p><h3 id="_3-2-用文件和记录承载稳定事实" tabindex="-1">3.2 用文件和记录承载稳定事实 <a class="header-anchor" href="#_3-2-用文件和记录承载稳定事实" aria-label="Permalink to &quot;3.2 用文件和记录承载稳定事实&quot;">​</a></h3><p>项目规则写入 <code>AGENTS.md</code>，进度写入 <code>ROADMAP.md</code>，架构决策写入专门文档，测试结果保留为文件或日志。稳定事实不必依赖模型记住整段对话。</p><h3 id="_3-3-在自然阶段边界压缩" tabindex="-1">3.3 在自然阶段边界压缩 <a class="header-anchor" href="#_3-3-在自然阶段边界压缩" aria-label="Permalink to &quot;3.3 在自然阶段边界压缩&quot;">​</a></h3><p>完成调查、方案或一个实现阶段后，可以保留目标、决策、改动文件、验证证据和待办，压缩冗长探索过程。压缩的目标是提高信噪比，而不是抹掉关键依据。</p><h3 id="_3-4-一个线程只处理一个主任务" tabindex="-1">3.4 一个线程只处理一个主任务 <a class="header-anchor" href="#_3-4-一个线程只处理一个主任务" aria-label="Permalink to &quot;3.4 一个线程只处理一个主任务&quot;">​</a></h3><p>将无关问题不断追加到同一线程，会让权限、范围和完成条件相互污染。新目标若能独立验收，就应进入新线程或新工作树。</p><p><img src="'+d+'" alt="图 3：上下文从原始材料到高信噪摘要的压缩"></p><h2 id="四、从其他编码代理迁移要迁移工作流" tabindex="-1">四、从其他编码代理迁移要迁移工作流 <a class="header-anchor" href="#四、从其他编码代理迁移要迁移工作流" aria-label="Permalink to &quot;四、从其他编码代理迁移要迁移工作流&quot;">​</a></h2><h3 id="_4-1-不要逐个翻译命令名称" tabindex="-1">4.1 不要逐个翻译命令名称 <a class="header-anchor" href="#_4-1-不要逐个翻译命令名称" aria-label="Permalink to &quot;4.1 不要逐个翻译命令名称&quot;">​</a></h3><p>不同工具在会话、权限、规则、插件和自动化上的概念并不完全一一对应。只寻找“某命令在 Codex 里叫什么”，容易保留旧工具的使用习惯，却错过新系统的原生边界。</p><h3 id="_4-2-先列出真正依赖的能力" tabindex="-1">4.2 先列出真正依赖的能力 <a class="header-anchor" href="#_4-2-先列出真正依赖的能力" aria-label="Permalink to &quot;4.2 先列出真正依赖的能力&quot;">​</a></h3><p>盘点现有工作流：项目规则放在哪里，常用自动化如何触发，外部工具怎样连接，权限怎样批准，任务怎样验证和发布。然后再为每项能力选择 Codex 中合适的配置、Skill、MCP 或脚本。</p><h3 id="_4-3-用一个真实项目做双轨验证" tabindex="-1">4.3 用一个真实项目做双轨验证 <a class="header-anchor" href="#_4-3-用一个真实项目做双轨验证" aria-label="Permalink to &quot;4.3 用一个真实项目做双轨验证&quot;">​</a></h3><p>选择规模适中、测试完备的项目，让旧流程和新流程完成同一组任务。比较结果质量、耗时、人工干预和安全边界，逐步迁移，而不是一次性替换全部团队工具。</p><h3 id="_4-4-清理重复事实源" tabindex="-1">4.4 清理重复事实源 <a class="header-anchor" href="#_4-4-清理重复事实源" aria-label="Permalink to &quot;4.4 清理重复事实源&quot;">​</a></h3><p>迁移期间最危险的是两套规则长期并存。确认新流程稳定后，应明确哪个文件是当前事实源，旧配置是归档还是废弃，避免代理读取相互冲突的指令。</p><p><img src="'+n+'" alt="图 4：从旧代理工作流映射到 Codex 能力层"></p><h2 id="五、windows-的关键是环境一致性" tabindex="-1">五、Windows 的关键是环境一致性 <a class="header-anchor" href="#五、windows-的关键是环境一致性" aria-label="Permalink to &quot;五、Windows 的关键是环境一致性&quot;">​</a></h2><h3 id="_5-1-原生环境与-wsl-各有边界" tabindex="-1">5.1 原生环境与 WSL 各有边界 <a class="header-anchor" href="#_5-1-原生环境与-wsl-各有边界" aria-label="Permalink to &quot;5.1 原生环境与 WSL 各有边界&quot;">​</a></h3><p>Windows 原生工具适合依赖本机 GUI、PowerShell 和 Windows SDK 的项目；WSL 更接近 Linux 开发链，适合依赖 Bash、容器和类 Unix 工具的仓库。选择应由目标运行环境和工具链决定。</p><h3 id="_5-2-不要跨文件系统反复搬动构建" tabindex="-1">5.2 不要跨文件系统反复搬动构建 <a class="header-anchor" href="#_5-2-不要跨文件系统反复搬动构建" aria-label="Permalink to &quot;5.2 不要跨文件系统反复搬动构建&quot;">​</a></h3><p>在 Windows 路径和 WSL 路径之间频繁读取大量小文件，可能带来性能和权限差异。仓库、依赖与构建目录应尽量位于主要执行环境一侧。</p><h3 id="_5-3-路径、换行与脚本需要显式约定" tabindex="-1">5.3 路径、换行与脚本需要显式约定 <a class="header-anchor" href="#_5-3-路径、换行与脚本需要显式约定" aria-label="Permalink to &quot;5.3 路径、换行与脚本需要显式约定&quot;">​</a></h3><p>盘符路径、大小写、符号链接、可执行位和行尾格式都可能使“同一仓库”表现不同。把支持的平台、启动命令和换行策略写进项目文档，并在 CI 中覆盖目标环境。</p><h3 id="_5-4-凭据不要在两个环境随意复制" tabindex="-1">5.4 凭据不要在两个环境随意复制 <a class="header-anchor" href="#_5-4-凭据不要在两个环境随意复制" aria-label="Permalink to &quot;5.4 凭据不要在两个环境随意复制&quot;">​</a></h3><p>Windows 和 WSL 拥有不同的凭据存储与权限模型。应使用官方登录和安全存储方式，避免为了方便把 token 写入共享脚本或仓库文件。</p><p><img src="'+h+'" alt="图 5：Windows 原生、WSL 与仓库位置的环境边界"></p><h2 id="六、完整项目从需求合同开始" tabindex="-1">六、完整项目从需求合同开始 <a class="header-anchor" href="#六、完整项目从需求合同开始" aria-label="Permalink to &quot;六、完整项目从需求合同开始&quot;">​</a></h2><h3 id="_6-1-建立可运行的最小基线" tabindex="-1">6.1 建立可运行的最小基线 <a class="header-anchor" href="#_6-1-建立可运行的最小基线" aria-label="Permalink to &quot;6.1 建立可运行的最小基线&quot;">​</a></h3><p>先确认仓库能安装、构建、测试和启动，记录当前已知失败。没有基线，后续无法判断问题是代理引入还是原本存在。</p><h3 id="_6-2-让代理先输出实现地图" tabindex="-1">6.2 让代理先输出实现地图 <a class="header-anchor" href="#_6-2-让代理先输出实现地图" aria-label="Permalink to &quot;6.2 让代理先输出实现地图&quot;">​</a></h3><p>要求它定位入口、模块边界、数据模型、外部依赖和现有测试，再给出分阶段计划。人审查计划后才进入大范围修改，可以及早发现错误假设。</p><h3 id="_6-3-按垂直切片交付" tabindex="-1">6.3 按垂直切片交付 <a class="header-anchor" href="#_6-3-按垂直切片交付" aria-label="Permalink to &quot;6.3 按垂直切片交付&quot;">​</a></h3><p>每个切片同时包含最小业务行为、必要测试和文档，而不是先生成全部接口再一次性集成。垂直切片能更早产生可运行结果，并让反馈回路持续工作。</p><h3 id="_6-4-完成意味着代码之外也闭环" tabindex="-1">6.4 完成意味着代码之外也闭环 <a class="header-anchor" href="#_6-4-完成意味着代码之外也闭环" aria-label="Permalink to &quot;6.4 完成意味着代码之外也闭环&quot;">​</a></h3><p>最终交付要包含配置、错误处理、测试、使用说明、升级影响和已知限制。代理的总结必须和 Git diff、测试结果及实际运行证据一致。</p><p><img src="'+s+'" alt="图 6：完整项目从基线、切片到交付验收"></p><h2 id="七、一个可复用的决策框架" tabindex="-1">七、一个可复用的决策框架 <a class="header-anchor" href="#七、一个可复用的决策框架" aria-label="Permalink to &quot;七、一个可复用的决策框架&quot;">​</a></h2><p>当任务不理想时，依次检查：目标是否可验证，范围是否过大，上下文是否混杂，工具是否拿到真实证据，环境是否可重建，权限是否阻塞必要动作，验证是否快速可靠。只有这些条件基本成立，再评估模型是否需要更强推理或不同速度档位。</p><p>这套顺序能避免把工程系统问题误判成模型问题。换模型可能暂时改善结果，却不会修复缺失测试、错误目录、失效缓存或冲突规则。</p><h2 id="八、把速度定义为-更快得到可信结果" tabindex="-1">八、把速度定义为“更快得到可信结果” <a class="header-anchor" href="#八、把速度定义为-更快得到可信结果" aria-label="Permalink to &quot;八、把速度定义为“更快得到可信结果”&quot;">​</a></h2><p>AI 编程的速度不应只统计首次补丁生成时间，而要统计从需求提出到证据齐全、可安全合并的总时间。一个慢几分钟但范围准确、测试可靠的结果，通常比瞬间生成却需要数小时人工排错更快。</p><p>模型选型、上下文压缩、环境治理和分段交付最终服务于同一目标：减少返工，让每一轮计算更接近可接受结果。</p><h2 id="九、参考资料" tabindex="-1">九、参考资料 <a class="header-anchor" href="#九、参考资料" aria-label="Permalink to &quot;九、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/30-models" target="_blank" rel="noreferrer">Codex 系列第 30 篇：模型选择</a></p><p><a href="https://coding.stormzhang.ai/codex/31-speed" target="_blank" rel="noreferrer">Codex 系列第 31 篇：速度与上下文</a></p><p><a href="https://coding.stormzhang.ai/codex/32-migrate-from-claude-code" target="_blank" rel="noreferrer">Codex 系列第 32 篇：迁移</a></p><p><a href="https://coding.stormzhang.ai/codex/33-windows" target="_blank" rel="noreferrer">Codex 系列第 33 篇：Windows</a></p><p><a href="https://coding.stormzhang.ai/codex/34-capstone" target="_blank" rel="noreferrer">Codex 系列第 34 篇：完整项目</a></p><p><a href="https://developers.openai.com/codex/" target="_blank" rel="noreferrer">OpenAI Codex 官方文档</a></p>',76)])])}const g=e(c,[["render",p]]);export{f as __pageData,g as default};
